document.querySelectorAll('[data-lab="PM14-I1"]').forEach(root=>{const z=root.dataset.lang==='zh',h=root.querySelector('[data-field="h"]'),w=root.querySelector('[data-field="w"]'),out=root.querySelector('[data-field="out"]');const X=v=>80+585*v/6,Y=v=>340-295*v/100,T=(H,W)=>H*H/(Math.PI*Math.PI*.1)*Math.log(4/Math.PI*(240-W)/(100-W));let labels='';[0,1,2,3,4,5,6].forEach(v=>labels+=`<text x="${X(v)}" y="369" text-anchor="middle">${v}</text>`);[0,20,40,60,80,100].forEach(v=>labels+=`<text x="66" y="${Y(v)+6}" text-anchor="end">${v}</text>`);root.querySelector('[data-field="ticks"]').innerHTML=labels;function path(W){return Array.from({length:61},(_,i)=>`${i?'L':'M'}${X(i/10)} ${Y(T(i/10,W))}`).join(' ')}root.querySelector('[data-field="ref"]').setAttribute('d',path(40));function update(){const H=+h.value,W=+w.value,t=T(H,W);root.querySelector('[data-field="curve"]').setAttribute('d',path(W));const d=root.querySelector('[data-field="dot"]');d.setAttribute('cx',X(H));d.setAttribute('cy',Y(t));out.textContent=z?`H=${H.toFixed(1)} mm，Tw=${W}°C，模型中心冷却时间 ${t.toFixed(2)} s；相同模温下2 mm厚度需 ${T(2,W).toFixed(2)} s，当前时间是其 ${(H*H/4).toFixed(2)} 倍。此值按规定中心温度计算，整机周期还包含充填、开合模和取件等过程。`:`H = ${H.toFixed(1)} mm; Tw = ${W}°C; modeled center-cooling time ${t.toFixed(2)} s. At the same wall temperature, a 2 mm plate needs ${T(2,W).toFixed(2)} s; the current time is ${(H*H/4).toFixed(2)} times that value. This center-temperature criterion is one part of a cycle that also includes filling, mold motion and ejection.`;}h.addEventListener('input',update);w.addEventListener('input',update);update();});